const HEX_LAYOUT = {"Калининградская область": [0, 3, "КЛГ"], "Мурманская область": [4, 0, "МУР"], "Архангельская область и Ненецкий АО": [7, 1, "АРХ"], "Республика Карелия": [4, 1, "КАР"], "Санкт-Петербург": [3, 2, "СПБ"], "Ленинградская область": [4, 2, "ЛЕН"], "Псковская область": [2, 3, "ПСК"], "Новгородская область": [4, 3, "НВГ"], "Вологодская область": [6, 2, "ВЛГ"], "Республика Коми": [8, 2, "КОМ"], "Тверская область": [5, 4, "ТВР"], "Смоленская область": [3, 4, "СМЛ"], "Брянская область": [2, 5, "БРЯ"], "Калужская область": [4, 5, "КЛЖ"], "Москва": [6, 5, "МСК"], "Московская область": [5, 5, "МО"], "Ярославская область": [6, 4, "ЯРС"], "Костромская область": [7, 4, "КСТ"], "Ивановская область": [7, 5, "ИВН"], "Владимирская область": [8, 5, "ВЛД"], "Орловская область": [4, 6, "ОРЛ"], "Тульская область": [5, 6, "ТУЛ"], "Рязанская область": [7, 6, "РЯЗ"], "Белгородская область": [2, 7, "БЕЛ"], "Курская область": [3, 7, "КУР"], "Липецкая область": [5, 7, "ЛПЦ"], "Тамбовская область": [7, 7, "ТАМ"], "Воронежская область": [4, 8, "ВРН"], "Республика Крым": [1, 10, "КРМ"], "Севастополь": [2, 10, "СЕВ"], "Ростовская область": [4, 10, "РСТ"], "Республика Адыгея": [3, 11, "АДГ"], "Краснодарский край": [4, 11, "КРД"], "Карачаево-Черкесская Республика": [5, 11, "КЧР"], "Ставропольский край": [6, 11, "СТВ"], "Кабардино-Балкарская Республика": [5, 12, "КБР"], "Республика Северная Осетия": [6, 12, "РСО"], "Республика Ингушетия": [7, 12, "ИНГ"], "Чеченская Республика": [8, 12, "ЧЕЧ"], "Республика Дагестан": [9, 12, "ДАГ"], "Республика Калмыкия": [7, 10, "КЛМ"], "Астраханская область": [8, 9, "АСТ"], "Волгоградская область": [7, 9, "ВГД"], "Республика Мордовия": [9, 6, "МОР"], "Нижегородская область": [10, 5, "НН"], "Чувашская Республика": [10, 6, "ЧУВ"], "Республика Марий Эл": [11, 5, "МАР"], "Кировская область": [10, 4, "КИР"], "Пензенская область": [10, 7, "ПНЗ"], "Ульяновская область": [11, 7, "УЛЬ"], "Республика Татарстан": [12, 6, "ТАТ"], "Самарская область": [13, 7, "САМ"], "Саратовская область": [14, 8, "САР"], "Оренбургская область": [14, 7, "ОРБ"], "Удмуртская Республика": [12, 5, "УДМ"], "Пермский край": [12, 4, "ПЕР"], "Республика Башкортостан": [13, 5, "БШК"], "Курганская область": [14, 4, "КРГ"], "Челябинская область": [14, 5, "ЧЛБ"], "Свердловская область": [13, 4, "СВР"], "Тюменская область": [15, 3, "ТЮМ"], "Ханты-Мансийский АО": [15, 2, "ХМ"], "Ямало-Ненецкий АО": [15, 1, "ЯН"], "Омская область": [16, 4, "ОМС"], "Томская область": [17, 3, "ТОМ"], "Новосибирская область": [17, 4, "НСК"], "Кемеровская область": [18, 4, "КЕМ"], "Алтайский край": [18, 5, "АЛК"], "Республика Алтай": [17, 6, "АЛТ"], "Республика Хакасия": [19, 5, "ХАК"], "Красноярский край": [18, 2, "КРЯ"], "Республика Тыва": [19, 6, "ТЫВ"], "Иркутская область": [20, 4, "ИРК"], "Республика Бурятия": [21, 5, "БУР"], "Забайкальский край": [22, 5, "ЗАБ"], "Республика Саха (Якутия)": [22, 2, "ЯКТ"], "Амурская область": [23, 5, "АМР"], "Еврейская А.обл.": [24, 5, "ЕАО"], "Хабаровский край": [24, 4, "ХБР"], "Приморский край": [24, 6, "ПРМ"], "Сахалинская область": [25, 7, "СХЛ"], "Камчатский край": [26, 3, "КМЧ"], "Магаданская область и Чукотский АО": [26, 1, "МГД"]};
const state = { data: Array.isArray(window.DEFAULT_DATA) ? window.DEFAULT_DATA : [], meta: window.DEFAULT_META || {}, view:'overview', direction:0, region:null, metric:'to', mapMode:'fit', charts:[] };

const $ = s => document.querySelector(s);
const $$ = s => Array.from(document.querySelectorAll(s));
const esc = s => String(s ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const num = v => typeof v === 'number' && Number.isFinite(v);
const pct = v => num(v) ? (v * 100).toFixed(1).replace('.', ',') + '%' : '—';
const score = v => num(v) ? String(+v.toFixed(2)).replace('.', ',') : '—';
const rank = v => num(v) ? Math.round(v) : '—';
const badgeClass = s => s === 'Высокая' ? 'high' : s === 'Средняя' ? 'mid' : 'low';
const metricLabel = () => state.metric === 'to' ? 'Оценка ТО Росреестра' : 'Комплексная оценка с учетом ППК';
const getVal = x => state.metric === 'to' ? x.v : x.cv;
const getRank = x => state.metric === 'to' ? x.r : x.cr;
const getPrevRank = x => x.pr;
const getScale = x => state.metric === 'to' ? x.sc : (x.cs || x.sc);
const getScoreText = x => state.metric === 'to' ? `${score(x.s)} / ${score(x.m)}` : `${pct(x.cv)} · ППК ${rank(x.ppr)}`;
function delta(curr, prev){ if(!num(curr)||!num(prev)) return null; return prev-curr; }
function deltaHtml(curr, prev){ const d = delta(curr, prev); if(d===null) return '<span class="delta-flat">—</span>'; if(d>0) return `<span class="delta-up">▲ ${d}</span>`; if(d<0) return `<span class="delta-down">▼ ${Math.abs(d)}</span>`; return '<span class="delta-flat">• 0</span>'; }
function mean(a){const x=a.filter(num);return x.length?x.reduce((s,v)=>s+v,0)/x.length:null;}
function destroyCharts(){state.charts.forEach(c=>{try{c.dispose()}catch(e){}});state.charts=[];}
function chart(el,opt){ if(!window.echarts||!el)return; const c=echarts.init(el); c.setOption(opt); state.charts.push(c); }
function chartBase(){ return {textStyle:{fontFamily:'Inter,Segoe UI,Arial',color:'#34465a'},tooltip:{trigger:'axis'},grid:{left:48,right:18,top:24,bottom:54,containLabel:true}}; }

function filteredData(){
  const fo=$('#foFilter').value, sc=$('#scaleFilter').value, q=$('#searchInput').value.trim().toLowerCase();
  return state.data.filter(x => (fo==='all'||x.fo===fo) && (sc==='all'||getScale(x)===sc) && (!q||x.n.toLowerCase().includes(q)));
}
function populateFilters(){
  const fos=[...new Set(state.data.map(x=>x.fo).filter(Boolean))].sort();
  $('#foFilter').innerHTML='<option value="all">Все округа</option>'+fos.map(x=>`<option>${esc(x)}</option>`).join('');
}
function updateMeta(){
  $('#periodText').textContent=state.meta.period||'Период из файла';
  $('#regionCount').textContent=state.data.length;
  $('#rankedCount').textContent=state.data.filter(x=>num(getRank(x))).length;
}
function setView(view){state.view=view;$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$$('.view').forEach(v=>v.classList.add('hidden'));$('#'+view+'View').classList.remove('hidden');render();}
function render(){destroyCharts();const data=filteredData(); if(state.view==='overview')renderOverview(data); if(state.view==='map')renderMap(data); if(state.view==='analytics')renderAnalytics(data); if(state.view==='ranking')renderRanking(data); if(state.view==='directions')renderDirections(data); if(state.view==='region')renderRegion(data); if(state.view==='diagnostics')renderDiagnostics(data); setTimeout(()=>state.charts.forEach(c=>c.resize()),0);}

function topBottom(data){
  const ranked = data.filter(x=>num(getRank(x))).sort((a,b)=>getRank(a)-getRank(b));
  return { top: ranked.slice(0,10), bottom: ranked.slice(-10).reverse() };
}
function foAverages(data){
  return [...new Set(data.map(x=>x.fo))].filter(Boolean).map(fo=>({fo,v:mean(data.filter(x=>x.fo===fo).map(getVal))})).sort((a,b)=>(b.v??0)-(a.v??0));
}
function movers(data){
  return [...data].filter(x=>num(getRank(x))&&num(getPrevRank(x))).map(x=>({...x,d:delta(getRank(x), getPrevRank(x))})).sort((a,b)=>Math.abs(b.d)-Math.abs(a.d));
}

function renderOverview(data){
  const root=$('#overviewDashboard'); const ranked=data.filter(x=>num(getRank(x))).sort((a,b)=>getRank(a)-getRank(b)); const leader=ranked[0]; const outsider=ranked[ranked.length-1];
  const avg=mean(data.map(getVal)); const avgTO=mean(data.map(x=>x.v)); const avgCombined=mean(data.map(x=>x.cv)); const high=data.filter(x=>getScale(x)==='Высокая').length;
  root.innerHTML=`
    <div class="section-head"><div><h2>Обзор комплексной оценки</h2><p>Сводная картина по выбранной группе территориальных органов. Сейчас показан режим: <strong>${metricLabel()}</strong>.</p></div></div>
    <div class="kpi-grid">
      <div class="kpi-card"><div class="label">ТО в выборке</div><div class="value">${data.length}</div><div class="sub">из ${state.data.length} в источнике</div></div>
      <div class="kpi-card"><div class="label">Среднее по выборке</div><div class="value">${pct(avg)}</div><div class="sub">${metricLabel()}</div></div>
      <div class="kpi-card accent-high"><div class="label">Высокая оценка</div><div class="value">${high}</div><div class="sub">${data.length?Math.round(high/data.length*100):0}% выборки</div></div>
      <div class="kpi-card"><div class="label">Лидер рейтинга</div><div class="value">${leader?rank(getRank(leader)):'—'}</div><div class="sub">${leader?`${esc(leader.n)} · ${pct(getVal(leader))}`:'Нет данных'}</div></div>
      <div class="kpi-card accent-low"><div class="label">Последнее место</div><div class="value">${outsider?rank(getRank(outsider)):'—'}</div><div class="sub">${outsider?`${esc(outsider.n)} · ${pct(getVal(outsider))}`:'Нет данных'}</div></div>
    </div>
    <div class="grid-2"><div class="panel"><div class="panel-title"><div><h3>ТОП-10 по текущему режиму</h3><p>${metricLabel()}, % выполнения</p></div></div><div id="topChart" class="chart"></div></div>
    <div class="panel"><div class="panel-title"><div><h3>Распределение оценок</h3><p>Высокая / средняя / низкая</p></div></div><div id="scaleChart" class="chart"></div></div></div>
    <div class="grid-2 equal"><div class="panel"><div class="panel-title"><div><h3>Средняя оценка по федеральным округам</h3><p>${metricLabel()}</p></div></div><div id="foChart" class="chart small"></div></div>
    <div class="panel"><div class="panel-title"><div><h3>Наибольшая динамика рейтинга</h3><p>Сравнение с IV кварталом 2025 года</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Регион</th><th>Было</th><th>Стало</th><th>Изменение</th></tr></thead><tbody>${moversRows(data)}</tbody></table></div></div></div>
    <div class="grid-2 equal"><div class="panel"><div class="panel-title"><div><h3>ТОП-10 и БОТТОМ-10</h3><p>Места в рейтинге: лучшие и последние</p></div></div><div id="bottomChart" class="chart small"></div></div>
    <div class="panel"><div class="panel-title"><div><h3>Средние значения по модели оценки</h3><p>Для сопоставления режимов расчета</p></div></div><div class="diag-grid"><div class="diag-item"><span>Средняя оценка ТО</span><strong>${pct(avgTO)}</strong></div><div class="diag-item"><span>Средняя с учетом ППК</span><strong>${pct(avgCombined)}</strong></div><div class="diag-item"><span>Медиана текущего режима</span><strong>${pct(mean(ranked.map(getVal)))}</strong></div></div><div class="note" style="margin-top:12px">Переключатель вверху позволяет моментально сравнивать классический рейтинг ТО и комплексную оценку с учетом ППК «Роскадастр».</div></div></div>`;
  const top=[...data].filter(x=>num(getVal(x))).sort((a,b)=>getVal(b)-getVal(a)).slice(0,10).reverse();
  chart($('#topChart'),{...chartBase(),xAxis:{type:'value',min:Math.max(0,Math.floor((Math.min(...top.map(x=>getVal(x)))*100-5)/5)*5),max:100,axisLabel:{formatter:'{value}%'}},yAxis:{type:'category',data:top.map(x=>x.n),axisLabel:{width:175,overflow:'truncate'}},series:[{type:'bar',data:top.map(x=>+(getVal(x)*100).toFixed(1)),barMaxWidth:20,itemStyle:{borderRadius:[0,6,6,0]}}]});
  const counts=['Высокая','Средняя','Низкая'].map(n=>({name:n,value:data.filter(x=>getScale(x)===n).length}));
  chart($('#scaleChart'),{tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['48%','72%'],center:['50%','44%'],label:{formatter:'{b}\n{c}'},data:counts}]});
  const fog=foAverages(data);
  chart($('#foChart'),{...chartBase(),xAxis:{type:'category',data:fog.map(x=>x.fo),axisLabel:{rotate:0}},yAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},series:[{type:'bar',data:fog.map(x=>num(x.v)?+(x.v*100).toFixed(1):null),barMaxWidth:34,itemStyle:{borderRadius:[6,6,0,0]}}]});
  const tb = topBottom(data); const cats=[...tb.top.map(x=>x.n),...tb.bottom.map(x=>x.n)]; const vals=[...tb.top.map(x=>+(getVal(x)*100).toFixed(1)),...tb.bottom.map(x=>+(getVal(x)*100).toFixed(1))];
  chart($('#bottomChart'),{...chartBase(),grid:{left:48,right:18,top:24,bottom:24,containLabel:true},xAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},yAxis:{type:'category',data:cats,axisLabel:{width:180,overflow:'truncate'}},series:[{type:'bar',data:vals,barMaxWidth:16,itemStyle:{borderRadius:[0,5,5,0]}}]});
}
function moversRows(data){return movers(data).slice(0,10).map(x=>`<tr><td>${esc(x.n)}</td><td>${rank(getPrevRank(x))}</td><td><span class="rank-pill">${rank(getRank(x))}</span></td><td>${deltaHtml(getRank(x),getPrevRank(x))}</td></tr>`).join('')||'<tr><td colspan="4">Нет данных</td></tr>';}


function renderMap(data){
  const root = $('#mapDashboard');
  const selected = new Set(data.map(x=>x.n));
  const all = state.data.filter(x=>HEX_LAYOUT[x.n]);
  const maxCol = Math.max(...Object.values(HEX_LAYOUT).map(v=>v[0]));
  const maxRow = Math.max(...Object.values(HEX_LAYOUT).map(v=>v[1]));

  const mobile = window.matchMedia('(max-width: 700px)').matches;
  const fitMode = state.mapMode === 'fit';
  const geom = fitMode
    ? { cellW: 74, cellH: 64, stepX: 56, stepY: 42, offsetX: 28 }
    : { cellW: 84, cellH: 74, stepX: 63, stepY: 48, offsetX: 32 };

  const { cellW, cellH, stepX, stepY, offsetX } = geom;
  const naturalWidth = maxCol * stepX + cellW + offsetX + 24;
  const naturalHeight = maxRow * stepY + cellH + 24;

  const high = data.filter(x=>getScale(x)==='Высокая').length;
  const mid = data.filter(x=>getScale(x)==='Средняя').length;
  const low = data.filter(x=>getScale(x)==='Низкая').length;
  const leader = [...data].filter(x=>num(getRank(x))).sort((a,b)=>getRank(a)-getRank(b))[0];
  const compactText = fitMode && mobile;

  const cells = all.map(x=>{
    const [c,r,label]=HEX_LAYOUT[x.n];
    const cls = getScale(x)==='Высокая' ? 'high' : getScale(x)==='Средняя' ? 'mid' : 'low';
    const dim = selected.has(x.n) ? '' : ' dim';
    const left = c*stepX + (r%2?offsetX:0);
    const top = r*stepY;
    return `<button type="button" class="hex-cell ${cls}${dim}" data-region="${esc(x.n)}" style="left:${left}px;top:${top}px;width:${cellW}px;height:${cellH}px" aria-label="${esc(x.n)}, ${pct(getVal(x))}, место ${rank(getRank(x))}" title="${esc(x.n)} · ${pct(getVal(x))} · место ${rank(getRank(x))}">
      <span class="hex-cell-label">${esc(label)}</span>
      <span class="hex-cell-value">${pct(getVal(x))}</span>
      <span class="hex-cell-rank">место ${rank(getRank(x))}</span>
    </button>`;
  }).join('');

  root.innerHTML = `
    <div class="section-head map-section-head">
      <div><h2>Карта России сотами</h2><p>Плотная сотовая картограмма регионов без лишних пробелов. Цвет показывает уровень оценки в режиме <strong>${metricLabel()}</strong>.</p></div>
      <div class="map-controls">
        <div class="segmented" role="group" aria-label="Режим карты">
          <button type="button" class="segment-btn ${fitMode?'active':''}" data-map-mode="fit">Вся Россия</button>
          <button type="button" class="segment-btn ${state.mapMode==='detail'?'active':''}" data-map-mode="detail">Подробно</button>
        </div>
        <div class="legend-inline"><span class="legend-item"><i class="legend-swatch high"></i>Высокая</span><span class="legend-item"><i class="legend-swatch mid"></i>Средняя</span><span class="legend-item"><i class="legend-swatch low"></i>Низкая</span><span class="legend-item"><i class="legend-swatch dim"></i>Вне фильтра</span></div>
      </div>
    </div>
    <div class="panel map-panel">
      <div class="panel-title map-panel-title"><div><h3>${fitMode?'Вся Россия на одном экране':'Подробная плотная карта'}</h3><p>${fitMode?'Карта уплотнена: соты соприкасаются и общий контур читается лучше.':'Крупные плотные соты с процентом и местом. Карту можно прокручивать по горизонтали.'}</p></div><div class="note">В фильтре: <strong>${data.length}</strong> регионов</div></div>
      <div class="hex-map-scroll ${fitMode?'fit-mode':'detail-mode'} dense-map">
        <div class="hex-map-stage" style="--map-natural-width:${naturalWidth}px;--map-natural-height:${naturalHeight}px">
          <div class="hex-map ${compactText?'compact-text':''}" style="width:${naturalWidth}px;height:${naturalHeight}px">${cells}</div>
        </div>
      </div>
      ${fitMode && mobile ? '<div class="map-mobile-hint">В режиме «Вся Россия» карта автоматически ужимается так, чтобы был виден весь контур страны. Для чтения процентов и мест переключитесь на «Подробно».</div>' : ''}
    </div>
    <div class="grid-2 equal">
      <div class="panel"><div class="panel-title"><div><h3>Сводка по текущему фильтру</h3><p>${metricLabel()}</p></div></div><div class="map-side-grid"><div class="map-mini-card"><span>Высокая оценка</span><strong>${high}</strong></div><div class="map-mini-card"><span>Средняя оценка</span><strong>${mid}</strong></div><div class="map-mini-card"><span>Низкая оценка</span><strong>${low}</strong></div></div></div>
      <div class="panel"><div class="panel-title"><div><h3>Лидер на карте</h3><p>Лучший результат по текущему режиму</p></div></div><div class="note"><strong>${leader?esc(leader.n):'Нет данных'}</strong><br>Федеральный округ: ${leader?esc(leader.fo):'—'}<br>Значение: ${leader?pct(getVal(leader)):'—'}<br>Место в рейтинге: ${leader?rank(getRank(leader)):'—'}<br><br>Нажмите на соту в подробном режиме, чтобы открыть карточку региона.</div></div>
    </div>`;

  $$('#mapDashboard [data-map-mode]').forEach(btn=>btn.addEventListener('click',()=>{
    state.mapMode = btn.dataset.mapMode;
    render();
  }));

  $$('#mapDashboard .hex-cell').forEach(btn=>btn.addEventListener('click',()=>{
    state.region = btn.dataset.region;
    setView('region');
  }));

  const applyMapScale = ()=>{
    const scroll = $('#mapDashboard .hex-map-scroll.fit-mode');
    const stage = $('#mapDashboard .hex-map-stage');
    const map = $('#mapDashboard .hex-map');
    if(!scroll || !stage || !map) return;
    const available = Math.max(260, scroll.clientWidth - 2);
    const scale = Math.min(1, available / naturalWidth);
    map.style.transform = `scale(${scale})`;
    map.style.transformOrigin = '0 0';
    stage.style.width = `${naturalWidth * scale}px`;
    stage.style.height = `${naturalHeight * scale}px`;
  };
  if(fitMode) requestAnimationFrame(applyMapScale);
}

function renderAnalytics(data){
  const root=$('#analyticsDashboard');
  const usable=data.filter(x=>num(x.v));
  const avgTO=mean(usable.map(x=>x.v));
  const avgPPK=mean(usable.map(x=>x.ppv));
  const avgCombined=mean(usable.map(x=>x.cv));
  const ranked=usable.filter(x=>num(x.r)&&num(x.pr));
  const improved=ranked.filter(x=>delta(x.r,x.pr)>0).length;
  const worsened=ranked.filter(x=>delta(x.r,x.pr)<0).length;
  const stable=ranked.filter(x=>delta(x.r,x.pr)===0).length;
  const ppkImpact=usable.filter(x=>num(x.cv)&&num(x.v)).map(x=>({...x,impact:x.cv-x.v})).sort((a,b)=>b.impact-a.impact);
  const bestImpact=ppkImpact[0], worstImpact=ppkImpact[ppkImpact.length-1];
  const foStats=[...new Set(usable.map(x=>x.fo).filter(Boolean))].map(fo=>{
    const rows=usable.filter(x=>x.fo===fo);
    return {fo,to:mean(rows.map(x=>x.v)),ppk:mean(rows.map(x=>x.ppv)),combined:mean(rows.map(x=>x.cv)),n:rows.length};
  }).sort((a,b)=>(b.combined??0)-(a.combined??0));
  const dirStats=DIRECTIONS.map((name,i)=>{
    const vals=usable.map(x=>x.d?.[i]?.[1]).filter(num);
    const below90=usable.filter(x=>num(x.d?.[i]?.[1])&&x.d[i][1]<.90).length;
    return {name,short:SHORT[i],avg:mean(vals),below90,n:vals.length};
  }).filter(x=>num(x.avg)).sort((a,b)=>a.avg-b.avg);
  const weakestDir=dirStats[0], strongestDir=dirStats[dirStats.length-1];
  const attention=usable.map(x=>{
    const d=delta(x.r,x.pr);
    const weakDirs=(x.d||[]).filter(z=>num(z?.[1])&&z[1]<.90).length;
    let scoreRisk=0;
    if(num(x.v)) scoreRisk+=(1-x.v)*100;
    if(num(d)&&d<0) scoreRisk+=Math.abs(d)*.6;
    scoreRisk+=weakDirs*1.5;
    return {...x,d,weakDirs,scoreRisk};
  }).sort((a,b)=>b.scoreRisk-a.scoreRisk).slice(0,12);
  const moversAll=[...ranked].map(x=>({...x,d:delta(x.r,x.pr)}));
  const gains=moversAll.filter(x=>x.d>0).sort((a,b)=>b.d-a.d).slice(0,8);
  const losses=moversAll.filter(x=>x.d<0).sort((a,b)=>a.d-b.d).slice(0,8);
  const bestFO=foStats[0], worstFO=foStats[foStats.length-1];
  const changedClass=usable.filter(x=>x.sc && x.cs && x.sc!==x.cs).length;

  root.innerHTML=`
    <div class="section-head"><div><h2>Управленческая аналитика</h2><p>Автоматические выводы по рейтингу, ППК «Роскадастр», федеральным округам и направлениям деятельности.</p></div><div class="note">Фильтры сверху применяются ко всей аналитике. Динамика рейтинга относится к сравнению с IV кварталом 2025 года.</div></div>
    <div class="kpi-grid">
      <div class="kpi-card"><div class="label">Средняя оценка ТО</div><div class="value">${pct(avgTO)}</div><div class="sub">по текущей выборке</div></div>
      <div class="kpi-card"><div class="label">С учетом ППК</div><div class="value">${pct(avgCombined)}</div><div class="sub">ППК отдельно: ${pct(avgPPK)}</div></div>
      <div class="kpi-card accent-high"><div class="label">Улучшили место</div><div class="value">${improved}</div><div class="sub">из ${ranked.length} сопоставимых ТО</div></div>
      <div class="kpi-card accent-low"><div class="label">Снизили место</div><div class="value">${worsened}</div><div class="sub">без изменений: ${stable}</div></div>
      <div class="kpi-card"><div class="label">Смена уровня из-за ППК</div><div class="value">${changedClass}</div><div class="sub">ТО изменили категорию оценки</div></div>
    </div>

    <div class="grid-2 equal">
      <div class="panel"><div class="panel-title"><div><h3>Ключевые выводы</h3><p>Автоматически сформировано по текущей выборке</p></div></div>
        <div class="insight-list">
          <div class="insight-item positive"><strong>Лучший федеральный округ:</strong> ${bestFO?esc(bestFO.fo):'—'} — ${bestFO?pct(bestFO.combined):'—'} по комплексной оценке.</div>
          <div class="insight-item warning"><strong>Округ с минимальным средним:</strong> ${worstFO?esc(worstFO.fo):'—'} — ${worstFO?pct(worstFO.combined):'—'}.</div>
          <div class="insight-item negative"><strong>Самое слабое направление:</strong> ${weakestDir?esc(weakestDir.name):'—'} — среднее ${weakestDir?pct(weakestDir.avg):'—'}, ниже 90% у ${weakestDir?weakestDir.below90:0} ТО.</div>
          <div class="insight-item positive"><strong>Самое сильное направление:</strong> ${strongestDir?esc(strongestDir.name):'—'} — среднее ${strongestDir?pct(strongestDir.avg):'—'}.</div>
          <div class="insight-item"><strong>Наибольшее влияние ППК вверх:</strong> ${bestImpact?esc(bestImpact.n):'—'} — ${(bestImpact&&num(bestImpact.impact)?(bestImpact.impact*100).toFixed(1).replace('.',','):'—')} п.п.; <strong>наибольшее вниз:</strong> ${worstImpact?esc(worstImpact.n):'—'} — ${(worstImpact&&num(worstImpact.impact)?(worstImpact.impact*100).toFixed(1).replace('.',','):'—')} п.п.</div>
        </div>
      </div>
      <div class="panel"><div class="panel-title"><div><h3>ТО vs ППК «Роскадастр»</h3><p>Каждая точка — территориальный орган; диагональ показывает равные значения</p></div></div><div id="analyticsScatter" class="chart"></div><div class="quadrant-note">Чем выше и правее точка, тем выше оба компонента. Точки заметно ниже диагонали указывают на более слабый результат ППК относительно ТО.</div></div>
    </div>

    <div class="grid-2 equal">
      <div class="panel"><div class="panel-title"><div><h3>Федеральные округа</h3><p>Средние: ТО / ППК / комплексная оценка</p></div></div><div id="analyticsFo" class="chart"></div></div>
      <div class="panel"><div class="panel-title"><div><h3>Направления — зоны внимания</h3><p>Среднее значение и количество ТО ниже 90%</p></div></div><div id="analyticsDirections" class="chart"></div></div>
    </div>

    <div class="grid-2 equal">
      <div class="panel"><div class="panel-title"><div><h3>Динамика рейтинга</h3><p>Наибольший рост и снижение позиций</p></div></div><div id="analyticsMoves" class="chart small"></div></div>
      <div class="panel"><div class="panel-title"><div><h3>Регионы, требующие внимания</h3><p>Низкая оценка, отрицательная динамика и слабые направления</p></div></div><div class="table-wrap"><table class="data-table analytics-table"><thead><tr><th>Регион</th><th>Оценка ТО</th><th>Место</th><th>Динамика</th><th>Напр. &lt;90%</th></tr></thead><tbody>${attention.map(x=>`<tr class="clickable-row" data-region="${esc(x.n)}"><td><strong>${esc(x.n)}</strong></td><td>${pct(x.v)}<span class="mini-bar"><span style="width:${Math.max(0,Math.min(100,(x.v||0)*100))}%"></span></span></td><td>${rank(x.r)}</td><td>${deltaHtml(x.r,x.pr)}</td><td>${x.weakDirs}</td></tr>`).join('')}</tbody></table></div></div>
    </div>`;

  $$('#analyticsDashboard .clickable-row').forEach(tr=>tr.addEventListener('click',()=>{state.region=tr.dataset.region;setView('region');}));

  const scatter=usable.filter(x=>num(x.v)&&num(x.ppv)).map(x=>[+(x.v*100).toFixed(1),+(x.ppv*100).toFixed(1),x.n,x.fo,+(x.cv*100).toFixed(1)]);
  chart($('#analyticsScatter'),{tooltip:{trigger:'item',formatter:p=>`${esc(p.data[2])}<br>ТО: ${p.data[0]}%<br>ППК: ${p.data[1]}%<br>Комплексная: ${p.data[4]}%`},grid:{left:48,right:18,top:24,bottom:48,containLabel:true},xAxis:{name:'ТО, %',type:'value',min:Math.max(0,Math.floor(Math.min(...scatter.map(x=>x[0]),50)/5)*5),max:100},yAxis:{name:'ППК, %',type:'value',min:Math.max(0,Math.floor(Math.min(...scatter.map(x=>x[1]),35)/5)*5),max:100},series:[{type:'scatter',data:scatter,symbolSize:v=>8+Math.max(0,(v[4]-70)/4),itemStyle:{opacity:.72},markLine:{silent:true,symbol:'none',lineStyle:{type:'dashed'},data:[[{coord:[50,50]},{coord:[100,100]}]]}}]});

  chart($('#analyticsFo'),{tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:40,right:16,top:24,bottom:70,containLabel:true},xAxis:{type:'category',data:foStats.map(x=>x.fo)},yAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},series:[{name:'ТО',type:'bar',data:foStats.map(x=>num(x.to)?+(x.to*100).toFixed(1):null)},{name:'ППК',type:'bar',data:foStats.map(x=>num(x.ppk)?+(x.ppk*100).toFixed(1):null)},{name:'Комплексная',type:'line',smooth:true,data:foStats.map(x=>num(x.combined)?+(x.combined*100).toFixed(1):null)}]});

  const dirView=dirStats.slice(0,10).reverse();
  chart($('#analyticsDirections'),{tooltip:{trigger:'axis'},grid:{left:48,right:42,top:22,bottom:30,containLabel:true},xAxis:[{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},{type:'value',min:0,max:Math.max(5,...dirView.map(x=>x.below90)),position:'top'}],yAxis:{type:'category',data:dirView.map(x=>x.short)},series:[{name:'Среднее',type:'bar',data:dirView.map(x=>+(x.avg*100).toFixed(1)),barMaxWidth:18,itemStyle:{borderRadius:[0,5,5,0]}},{name:'ТО ниже 90%',type:'line',xAxisIndex:1,data:dirView.map(x=>x.below90),symbolSize:7}]});

  const moveRows=[...losses.slice().reverse(),...gains];
  chart($('#analyticsMoves'),{tooltip:{trigger:'axis',axisPointer:{type:'shadow'}},grid:{left:48,right:18,top:20,bottom:26,containLabel:true},xAxis:{type:'value',name:'позиций'},yAxis:{type:'category',data:moveRows.map(x=>x.n),axisLabel:{width:150,overflow:'truncate'}},series:[{type:'bar',data:moveRows.map(x=>x.d),barMaxWidth:16,itemStyle:{borderRadius:[4,4,4,4]}}]});
}

function renderRanking(data){
  const avg = mean(data.map(getVal));
  const rows=[...data].sort((a,b)=>(getRank(a)??999)-(getRank(b)??999)||((getVal(b)??0)-(getVal(a)??0)));
  $('#rankingDashboard').innerHTML=`<div class="section-head"><div><h2>Итоговый рейтинг территориальных органов</h2><p>Текущее место, динамика и сопоставление со средним. Активный режим: <strong>${metricLabel()}</strong>.</p></div><div class="note">Нажмите на строку региона, чтобы открыть карточку территориального органа.</div></div>
  <div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Место</th><th>Регион</th><th>ФО</th><th>Оценка</th><th>Достижение</th><th>Отклонение от среднего</th><th>Баллы / модель</th><th>IV кв. 2025</th><th>Динамика</th><th>ППК</th></tr></thead><tbody>${rows.map(x=>`<tr class="clickable-row" data-region="${esc(x.n)}"><td><span class="rank-pill">${rank(getRank(x))}</span></td><td><strong>${esc(x.n)}</strong></td><td>${esc(x.fo)}</td><td><span class="badge ${badgeClass(getScale(x))}">${esc(getScale(x))}</span></td><td>${pct(getVal(x))}<div class="progress"><span style="width:${Math.max(0,Math.min(100,(getVal(x)||0)*100))}%"></span></div></td><td>${num(getVal(x))&&num(avg)?((getVal(x)-avg)>=0?'<span class="delta-up">+':'<span class="delta-down">')+((Math.abs(getVal(x)-avg)*100).toFixed(1).replace('.',','))+' п.п.</span>':'—'}</td><td>${getScoreText(x)}</td><td>${rank(getPrevRank(x))}</td><td>${deltaHtml(getRank(x),getPrevRank(x))}</td><td>${rank(x.ppr)} · ${pct(x.ppv)}</td></tr>`).join('')}</tbody></table></div></div>`;
  $$('#rankingDashboard .clickable-row').forEach(tr=>tr.addEventListener('click',()=>{state.region=tr.dataset.region; setView('region');}));
}

function renderDirections(data){
  if(state.direction>=DIRECTIONS.length)state.direction=0; const i=state.direction;
  const rows=[...data].filter(x=>x.d&&x.d[i]&&num(x.d[i][1])).sort((a,b)=>(a.d[i][0]??999)-(b.d[i][0]??999)||b.d[i][1]-a.d[i][1]);
  const avgByDir=DIRECTIONS.map((_,j)=>mean(data.map(x=>x.d?.[j]?.[1])));
  $('#directionsDashboard').innerHTML=`<div class="section-head"><div><h2>Оценка по направлениям</h2><p>Сравнение ТО по каждому из 12 направлений деятельности.</p></div><div class="toolbar"><select id="directionSelect" class="inline-select">${DIRECTIONS.map((n,j)=>`<option value="${j}" ${j===i?'selected':''}>${esc(n)}</option>`).join('')}</select></div></div>
  <div class="grid-2"><div class="panel"><div class="panel-title"><div><h3>Средняя степень достижения по направлениям</h3><p>По текущей выборке</p></div></div><div id="dirAvgChart" class="chart"></div></div><div class="panel"><div class="panel-title"><div><h3>Лидеры: ${esc(DIRECTIONS[i])}</h3><p>Топ-15 по степени достижения</p></div></div><div id="dirTopChart" class="chart"></div></div></div>
  <div class="grid-2 equal"><div class="panel"><div class="panel-title"><div><h3>Краткий вывод по направлению</h3><p>${esc(DIRECTIONS[i])}</p></div></div><div class="diag-grid"><div class="diag-item"><span>Среднее по РФ</span><strong>${pct(avgByDir[i])}</strong></div><div class="diag-item"><span>Лидер</span><strong>${rows.length?esc(rows[0].n):'—'}</strong></div><div class="diag-item"><span>Последний в выборке</span><strong>${rows.length?esc(rows[rows.length-1].n):'—'}</strong></div></div></div><div class="panel"><div class="panel-title"><div><h3>Антирейтинг по направлению</h3><p>Последние 10 территориальных органов</p></div></div><div id="dirLowChart" class="chart small"></div></div></div>
  <div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Место</th><th>Регион</th><th>ФО</th><th>Достижение</th><th>Баллы</th><th>Общая оценка ТО</th></tr></thead><tbody>${rows.map(x=>`<tr class="clickable-row" data-region="${esc(x.n)}"><td><span class="rank-pill">${rank(x.d[i][0])}</span></td><td><strong>${esc(x.n)}</strong></td><td>${esc(x.fo)}</td><td>${pct(x.d[i][1])}</td><td>${score(x.d[i][2])} / ${score(x.d[i][3])}</td><td>${pct(x.v)}</td></tr>`).join('')||'<tr><td colspan="6">По направлению нет данных</td></tr>'}</tbody></table></div></div>`;
  $('#directionSelect').addEventListener('change',e=>{state.direction=+e.target.value;render();});
  $$('#directionsDashboard .clickable-row').forEach(tr=>tr.addEventListener('click',()=>{state.region=tr.dataset.region; setView('region');}));
  chart($('#dirAvgChart'),{...chartBase(),xAxis:{type:'category',data:SHORT,axisLabel:{rotate:35,fontSize:10}},yAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},series:[{type:'bar',data:avgByDir.map(v=>num(v)?+(v*100).toFixed(1):null),barMaxWidth:28,itemStyle:{borderRadius:[5,5,0,0]}}]});
  const top=[...rows].sort((a,b)=>b.d[i][1]-a.d[i][1]).slice(0,15).reverse();
  chart($('#dirTopChart'),{...chartBase(),xAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},yAxis:{type:'category',data:top.map(x=>x.n),axisLabel:{width:160,overflow:'truncate'}},series:[{type:'bar',data:top.map(x=>+(x.d[i][1]*100).toFixed(1)),barMaxWidth:18,itemStyle:{borderRadius:[0,5,5,0]}}]});
  const low=[...rows].sort((a,b)=>a.d[i][1]-b.d[i][1]).slice(0,10).reverse();
  chart($('#dirLowChart'),{...chartBase(),xAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},yAxis:{type:'category',data:low.map(x=>x.n),axisLabel:{width:160,overflow:'truncate'}},series:[{type:'bar',data:low.map(x=>+(x.d[i][1]*100).toFixed(1)),barMaxWidth:18,itemStyle:{borderRadius:[0,5,5,0]}}]});
}

function renderRegion(data){
  const pool=data.length?data:state.data; if(!pool.length){$('#regionDashboard').innerHTML='<div class="panel">Нет данных</div>';return;}
  let x=pool.find(z=>z.n===state.region)||pool[0]; state.region=x.n;
  const d=x.d||[]; const avgByDir=DIRECTIONS.map((_,j)=>mean(state.data.map(t=>t.d?.[j]?.[1])));
  const valid=d.map((z,i)=>({z,i})).filter(o=>num(o.z?.[1]));
  const rankedDirs=valid.map(o=>({i:o.i,name:DIRECTIONS[o.i],val:o.z[1],avg:avgByDir[o.i]})).sort((a,b)=>b.val-a.val);
  const strong=rankedDirs.slice(0,3), weak=rankedDirs.slice(-3).reverse();
  const avgCurr=mean(state.data.map(getVal));
  $('#regionDashboard').innerHTML=`<div class="section-head"><div><h2>Карточка территориального органа</h2><p>Профиль результата, сравнение со средним и сильные/слабые направления.</p></div><div class="toolbar"><select id="regionSelect" class="inline-select">${pool.slice().sort((a,b)=>a.n.localeCompare(b.n,'ru')).map(z=>`<option ${z.n===x.n?'selected':''}>${esc(z.n)}</option>`).join('')}</select></div></div>
  <div class="region-hero"><div><h2>${esc(x.n)}</h2><p>${esc(x.fo)} · <span class="badge ${badgeClass(getScale(x))}">${esc(getScale(x))}</span> · ${metricLabel().toLowerCase()} ${pct(getVal(x))}</p></div><div class="hero-rank"><span>Итоговое место</span>${rank(getRank(x))}</div></div>
  <div class="kpi-grid"><div class="kpi-card"><div class="label">Место в рейтинге</div><div class="value">${rank(getRank(x))}</div><div class="sub">${metricLabel()}</div></div><div class="kpi-card"><div class="label">Текущее значение</div><div class="value">${pct(getVal(x))}</div><div class="sub">среднее по РФ: ${pct(avgCurr)}</div></div><div class="kpi-card"><div class="label">Динамика</div><div class="value">${deltaHtml(getRank(x),getPrevRank(x))}</div><div class="sub">IV кв. 2025: ${rank(getPrevRank(x))} место</div></div><div class="kpi-card"><div class="label">Оценка ТО</div><div class="value">${pct(x.v)}</div><div class="sub">${score(x.s)} из ${score(x.m)} баллов</div></div><div class="kpi-card"><div class="label">ППК «Роскадастр»</div><div class="value">${pct(x.ppv)}</div><div class="sub">место филиала: ${rank(x.ppr)}</div></div></div>
  <div class="grid-2"><div class="panel"><div class="panel-title"><div><h3>Профиль по направлениям</h3><p>Сравнение региона со средним по РФ</p></div></div><div id="radarChart" class="chart"></div></div><div class="panel"><div class="panel-title"><div><h3>Сильные и слабые стороны</h3><p>Топ-3 и зоны внимания</p></div></div><div class="grid-2 equal"><div class="note"><strong>Сильные направления</strong><br>${strong.map(s=>`${esc(s.name)} — <strong>${pct(s.val)}</strong>`).join('<br>')||'—'}</div><div class="note"><strong>Зоны внимания</strong><br>${weak.map(s=>`${esc(s.name)} — <strong>${pct(s.val)}</strong>`).join('<br>')||'—'}</div></div><div class="note" style="margin-top:12px"><strong>Отклонение от среднего по РФ:</strong> ${num(getVal(x))&&num(avgCurr)?((getVal(x)-avgCurr)>=0?'+':'')+((getVal(x)-avgCurr)*100).toFixed(1).replace('.',',')+' п.п.':'—'}</div></div></div>
  <div class="panel"><div class="panel-title"><div><h3>Направления деятельности</h3><p>Место, достижение и сравнение со средним</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Направление</th><th>Место</th><th>Достижение</th><th>Среднее по РФ</th><th>Отклонение</th><th>Баллы</th></tr></thead><tbody>${DIRECTIONS.map((n,i)=>`<tr><td>${esc(n)}</td><td>${rank(d[i]?.[0])}</td><td>${pct(d[i]?.[1])}</td><td>${pct(avgByDir[i])}</td><td>${num(d[i]?.[1])&&num(avgByDir[i])?((d[i][1]-avgByDir[i])>=0?'<span class="delta-up">+':'<span class="delta-down">')+((Math.abs(d[i][1]-avgByDir[i])*100).toFixed(1).replace('.',','))+' п.п.</span>':'—'}</td><td>${score(d[i]?.[2])} / ${score(d[i]?.[3])}</td></tr>`).join('')}</tbody></table></div></div>`;
  $('#regionSelect').addEventListener('change',e=>{state.region=e.target.value;render();});
  if(valid.length) chart($('#radarChart'),{tooltip:{},legend:{bottom:0},radar:{indicator:valid.map(o=>({name:SHORT[o.i],max:100})),radius:'60%',splitNumber:4},series:[{type:'radar',data:[{value:valid.map(o=>+(o.z[1]*100).toFixed(1)),name:x.n},{value:valid.map(o=>num(avgByDir[o.i])?+(avgByDir[o.i]*100).toFixed(1):0),name:'Среднее по РФ'}],areaStyle:{opacity:.12}}]});
}

function renderDiagnostics(data){
  const ranked=state.data.filter(x=>num(x.r)).length, combined=state.data.filter(x=>num(x.cr)).length, missing=state.data.filter(x=>!num(x.r)).map(x=>x.n);
  const dirs=DIRECTIONS.map((n,i)=>({n,c:state.data.filter(x=>num(x.d?.[i]?.[1])).length,avg:mean(state.data.map(x=>x.d?.[i]?.[1]))}));
  const byScale=['Высокая','Средняя','Низкая'].map(s=>({s,to:state.data.filter(x=>x.sc===s).length,combined:state.data.filter(x=>(x.cs||x.sc)===s).length}));
  $('#diagnosticsDashboard').innerHTML=`<div class="section-head"><div><h2>Диагностика данных</h2><p>Контроль распознавания структуры файла перед аналитикой.</p></div></div><div class="diag-grid"><div class="diag-item"><span>Территориальных органов</span><strong>${state.data.length}</strong></div><div class="diag-item"><span>Имеют итоговое место ТО</span><strong>${ranked}</strong></div><div class="diag-item"><span>Имеют место с учетом ППК</span><strong>${combined}</strong></div></div><div class="grid-2 equal" style="margin-top:14px"><div class="panel"><div class="panel-title"><div><h3>Полнота направлений</h3><p>Количество ТО с числовой оценкой</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Направление</th><th>ТО с данными</th><th>Среднее</th></tr></thead><tbody>${dirs.map(x=>`<tr><td>${esc(x.n)}</td><td>${x.c}</td><td>${pct(x.avg)}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-title"><div><h3>Распределение уровней оценки</h3></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Уровень</th><th>По ТО</th><th>С учетом ППК</th></tr></thead><tbody>${byScale.map(x=>`<tr><td>${x.s}</td><td>${x.to}</td><td>${x.combined}</td></tr>`).join('')}</tbody></table></div><div class="note" style="margin-top:12px"><strong>Период:</strong> ${esc(state.meta.period||'—')}<br><strong>Источник:</strong> ${esc(state.meta.source||'Excel')}<br><strong>Без итогового места ТО:</strong> ${missing.length?missing.map(esc).join(', '):'нет'}<br><br>Направление «Правовое обеспечение» в исходной таблице имеет нулевой максимально возможный балл, поэтому его числовая оценка не рассчитывается.</div></div></div>`;
}

function normalizeName(v){return String(v??'').trim().toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ');}
function fromWorkbook(wb,fileName){
  const names=wb.SheetNames||[]; const ratingName=names.find(n=>normalizeName(n).includes('рейтинг то')&&normalizeName(n).includes('ппк'))||names.find(n=>normalizeName(n).includes('рейтинг то'));
  const evalName=names.find(n=>normalizeName(n).includes('оценка и места по направлениям'))||names.find(n=>normalizeName(n).includes('места по направлениям'));
  if(!ratingName||!evalName) throw new Error('Не найдены листы рейтинга и оценки по направлениям');
  const a=XLSX.utils.sheet_to_json(wb.Sheets[ratingName],{header:1,raw:true,defval:null}); const b=XLSX.utils.sheet_to_json(wb.Sheets[evalName],{header:1,raw:true,defval:null});
  const rm=new Map(); a.forEach(r=>{if(typeof r?.[0]==='number'&&r?.[7])rm.set(normalizeName(r[7]),r)});
  const out=[]; b.forEach(r=>{if(typeof r?.[0]!=='number'||!r?.[1])return;const q=rm.get(normalizeName(r[1]));if(!q)return; const dirs=[]; for(let j=0;j<12;j++){const k=6+j*4; dirs.push([toNum(r[k]),toNum(r[k+1]),toNum(r[k+2]),toNum(r[k+3])]);} out.push({n:r[1],fo:q[1],r:toNum(q[6]),pr:toNum(q[2]),sc:r[2],v:toNum(r[3]),s:toNum(r[4]),m:toNum(r[5]),ppr:toNum(q[90]),ppv:toNum(q[91]),cr:toNum(q[98]),cs:q[99],cv:toNum(q[100]),d:dirs});});
  if(!out.length)throw new Error('Не удалось распознать строки территориальных органов');
  const title=String(a?.[0]?.[0]||b?.[0]?.[0]||''); const m=title.match(/([IVX]+\s+квартал\s+20\d{2}\s+года?)/i);
  return {data:out,meta:{period:m?m[1]:title.trim().slice(0,120)||'Период из файла',source:fileName}};
}
function toNum(v){return typeof v==='number'&&Number.isFinite(v)?v:null;}

$$('.nav-btn').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
['metricFilter','foFilter','scaleFilter'].forEach(id=>$('#'+id).addEventListener('change',e=>{ if(id==='metricFilter'){ state.metric = e.target.value; } render(); updateMeta(); }));
$('#searchInput').addEventListener('input',render);
$('#resetFilters').addEventListener('click',()=>{$('#metricFilter').value='to'; state.metric='to'; $('#foFilter').value='all';$('#scaleFilter').value='all';$('#searchInput').value='';render(); updateMeta();});
$('#fileInput').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;$('#parseStatus').textContent='Чтение…';try{const buf=await file.arrayBuffer();const wb=XLSX.read(buf,{type:'array'});const parsed=fromWorkbook(wb,file.name);state.data=parsed.data;state.meta=parsed.meta;state.region=null;populateFilters();updateMeta();$('#fileName').textContent=file.name;$('#parseStatus').textContent='Готово';render();}catch(err){console.error(err);$('#parseStatus').textContent='Ошибка';alert('Не удалось обработать Excel: '+err.message);}});
window.addEventListener('resize',()=>{state.charts.forEach(c=>c.resize()); if(state.view==='map'&&state.mapMode==='fit') render();});
populateFilters();updateMeta();render();
